func (dr *deleteRunner) Init(ctx context.Context) error {
    collName := dr.req.GetCollectionName()
    if err := validateCollectionName(collName); err != nil {
        return ErrWithLog(log, "Invalid collection name", err)
    }
    // ... schema, partition, and channel setup ...
    dr.plan, err = planparserv2.CreateRetrievePlanArgs(dr.schema.schemaHelper, dr.req.GetExpr(), ...)
    // Only validates filter expression syntax, not parameter exclusivity
}

Key Finding: No validation exists that checks for mutual exclusivity between 'filter' and 'ids' parameters. The handler only processes filter field, while 'ids' is silently ignored if present in JSON payload.
